// ====== แก้ตรงนี้เพื่อเปลี่ยนพารามิเตอร์ backtest ======
const OVERRIDE_START_DATE = '2026-08-10T00:00:00+07:00'; // วันที่จะจำลองว่าเริ่มหมัก (แทนของจริง)
const BATCH_ID = 2; // batch จริงที่จะดึงข้อมูล Pill/Controller/recipe มาใช้ (2 = Hazy DIPA ณ 19 ส.ค. — id เปลี่ยนได้ถ้า clear data แล้วลงทะเบียนใหม่ เช็คตาราง batches ก่อนเสมอ)
// ======================================================

const start = new Date(OVERRIDE_START_DATE);
const now = new Date();
const days = [];
let cursor = new Date(start);
while (cursor <= now) {
  days.push({
    json: {
      batch_id: BATCH_ID,
      override_start_date: OVERRIDE_START_DATE,
      cutoff: cursor.toISOString(),
      simulated_day_label: ((d) => { const bkk = new Date(d.getTime() + 7 * 3600000); return String(bkk.getUTCDate()).padStart(2,'0') + '/' + String(bkk.getUTCMonth()+1).padStart(2,'0') + '/' + bkk.getUTCFullYear(); })(cursor)
    }
  });
  cursor = new Date(cursor.getTime() + 24 * 3600 * 1000);
}
return days;

const items = $input.all();
const results = [];
items.forEach((it, idx) => {
  const d = it.json;
  const dayLabel = $('Get Simulated Readings').itemMatching(idx).json.simulated_day_label || '-';

  function fmt(v, n) {
    return v == null ? '-' : Number(v).toFixed(n);
  }

  let content = '🧪 TEST BACKTEST | ' + (d.beer_name || '?') + ' | จำลองผ่านไปถึงวันที่ ' + dayLabel + '\n'
    + 'เฟส: ' + d.detected_phase + (d.next_phase ? (' 🔜 ใกล้ ' + d.next_phase) : '') + '\n'
    + (d.pill_is_stale ? '⚠️ Pill เงียบ ' + fmt(d.pill_stale_hours, 1) + ' ชม.' + (d.estimated_beer_temp_c != null ? ' เบียร์ ≈' + fmt(d.estimated_beer_temp_c, 2) + '°C (ประมาณ)' : ' ประมาณอุณหภูมิไม่ได้') + '\n' : '')
    + 'gravity: ' + fmt(d.gravity_sg, 3) + ' SG, Pill: ' + fmt(d.temperature_c, 2) + '°C, ตู้ควบคุม: ' + fmt(d.controller_temp_c, 2) + '°C (target ' + fmt(d.target_temperature_c, 2) + '°C)\n\n'
    + (d.reasoning || '-')
    + (d.batch_ready_to_package ? '\n🎉 (จำลอง) cold crash ครบช่วง พร้อมบรรจุ' : '')
    + (d.recommended_controller_target_c != null
        ? ('\n\n🌡️ (จำลอง) แนะนำ target ' + fmt(d.recommended_controller_target_c, 2) + '°C (ให้ Pill ถึง ' + fmt(d.recommended_pill_temp_c, 2) + '°C)'
            + (d.pill_eta_text ? ('\n⏱️ ' + d.pill_eta_text) : ''))
        : '');

  // กัน overflow เผื่อ reasoning ยาวผิดปกติ (ลิมิต Discord content 2000 ตัวอักษร)
  if (content.length > 1900) content = content.slice(0, 1900) + '…';

  results.push({ json: { content } });
});
return results;

// เวลาอ้างอิงสำหรับให้ sub-workflow วิเคราะห์เฟส ("Phase Analysis Engine")
// backtest ใช้ cutoff ของวันจำลองนั้นแทนเวลาจริง (ต่างจาก Phase Analysis Cron
// ที่ stamp เป็นเวลาปัจจุบันจริงเสมอ) ให้ hoursSinceStart/ETA คำนวณตรงกับ
// "วันนี้จำลอง" ไม่ใช่วันนี้จริง
const items = $input.all();
return items.map((it) => ({
  json: {
    ...it.json,
    analysis_time_iso: it.json.cutoff
  }
}));
